CREATE TABLE orders (
  order_id     NUMBER PRIMARY KEY,
  customer_id  NUMBER       NOT NULL,
  amount       NUMBER(10,2) NOT NULL,
  status       VARCHAR2(20) NOT NULL
);

CREATE TABLE error_log (
  log_id     NUMBER GENERATED ALWAYS AS IDENTITY,
  logged_at  TIMESTAMP DEFAULT SYSTIMESTAMP,
  source     VARCHAR2(60),
  message    VARCHAR2(4000)
);

INSERT INTO orders VALUES (101, 1, 2500.00, 'NEW');
INSERT INTO orders VALUES (102, 2,  800.00, 'NEW');
INSERT INTO orders VALUES (103, 1, 1200.00, 'SHIPPED');
COMMIT;

CREATE OR REPLACE PROCEDURE log_error_plain (
  p_source  IN VARCHAR2,
  p_message IN VARCHAR2
) AS
BEGIN
  INSERT INTO error_log (source, message)
  VALUES (p_source, p_message);
END;
/

BEGIN
  UPDATE orders SET status = 'PAID' WHERE order_id = 101;
  RAISE_APPLICATION_ERROR(-20001, 'Payment gateway timeout');
EXCEPTION
  WHEN OTHERS THEN
    log_error_plain('pay_order', SQLERRM);
    ROLLBACK;
END;
/

SELECT COUNT(*) FROM error_log;

CREATE OR REPLACE PROCEDURE log_error (
  p_source  IN VARCHAR2,
  p_message IN VARCHAR2
) AS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO error_log (source, message)
  VALUES (p_source, p_message);
  COMMIT;  -- commits only this INSERT
END;
/

BEGIN
  UPDATE orders SET status = 'PAID' WHERE order_id = 101;
  RAISE_APPLICATION_ERROR(-20001, 'Payment gateway timeout');
EXCEPTION
  WHEN OTHERS THEN
    log_error('pay_order', SQLERRM);
    ROLLBACK;
END;
/

SELECT source, message FROM error_log;
SELECT order_id, status FROM orders WHERE order_id = 101;

CREATE TABLE order_audit (
  order_id    NUMBER,
  old_amount  NUMBER(10,2),
  new_amount  NUMBER(10,2),
  changed_by  VARCHAR2(128),
  changed_at  DATE
);

CREATE OR REPLACE TRIGGER trg_orders_amount_audit
  BEFORE UPDATE OF amount ON orders
  FOR EACH ROW
DECLARE
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO order_audit
  VALUES (:OLD.order_id, :OLD.amount, :NEW.amount, USER, SYSDATE);
  COMMIT;
END;
/

UPDATE orders SET amount = 2600 WHERE order_id = 101;
COMMIT;

UPDATE orders SET amount = 50 WHERE order_id = 102;
ROLLBACK;

SELECT order_id, old_amount, new_amount FROM order_audit;
SELECT order_id, amount FROM orders WHERE order_id IN (101, 102);

CREATE OR REPLACE FUNCTION tag_order_plain (p_order_id NUMBER)
  RETURN VARCHAR2
AS
BEGIN
  INSERT INTO error_log (source, message)
  VALUES ('report', 'Viewed order ' || p_order_id);
  RETURN 'ORDER-' || p_order_id;
END;
/

SELECT tag_order_plain(order_id) FROM orders;

CREATE OR REPLACE FUNCTION tag_order (p_order_id NUMBER)
  RETURN VARCHAR2
AS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO error_log (source, message)
  VALUES ('report', 'Viewed order ' || p_order_id);
  COMMIT;
  RETURN 'ORDER-' || p_order_id;
END;
/

SELECT order_id, tag_order(order_id) AS tag
  FROM orders
 ORDER BY order_id;

CREATE OR REPLACE PROCEDURE count_new_orders AS
  PRAGMA AUTONOMOUS_TRANSACTION;
  l_cnt NUMBER;
BEGIN
  SELECT COUNT(*) INTO l_cnt FROM orders WHERE status = 'NEW';
  DBMS_OUTPUT.PUT_LINE('Autonomous sees NEW: ' || l_cnt);
  COMMIT;
END;
/

SET SERVEROUTPUT ON
DECLARE
  l_cnt NUMBER;
BEGIN
  UPDATE orders SET status = 'NEW' WHERE order_id = 103;
  SELECT COUNT(*) INTO l_cnt FROM orders WHERE status = 'NEW';
  DBMS_OUTPUT.PUT_LINE('Main sees NEW: ' || l_cnt);
  count_new_orders;
  ROLLBACK;
END;
/

CREATE OR REPLACE PROCEDURE mark_order_checked (p_id NUMBER) AS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  UPDATE orders SET status = 'CHECKED' WHERE order_id = p_id;
  COMMIT;
END;
/

BEGIN
  UPDATE orders SET status = 'PAID' WHERE order_id = 101;
  mark_order_checked(101);   -- same row, locked by the caller
END;
/

